/* Banco de questões do Practice Exercises. Uma questão por linha.
   Campos: id, topic, level (easy|medium|hard), q (use ___ para a lacuna), options, answer (índice),
   explanation, accept (respostas aceitas no modo Written) e w ({q, accept}: enunciado alternativo no modo Written). */
const practiceQuestions=[
{"id":"ti-001","topic":"To vs. -ing","level":"medium","q":"I remember ___ him about the deadline yesterday.","options":["to remind","reminding","remind","to reminding"],"answer":1,"explanation":"After remember + -ing, we refer to a memory of a past action. 'Remember to + verb' means not forget a future/intended action."},
{"id":"ti-002","topic":"To vs. -ing","level":"easy","q":"Please remember ___ the final version before Friday.","options":["sending","to send","send","to sending"],"answer":1,"explanation":"Remember + to-infinitive refers to an action that still needs to be done."},
{"id":"ti-003","topic":"To vs. -ing","level":"easy","q":"He stopped ___ his emails because he was too busy.","options":["checking","to check","check","to checking"],"answer":0,"explanation":"Stop + -ing means cease the activity."},
{"id":"ti-004","topic":"To vs. -ing","level":"medium","q":"He stopped ___ his emails because he wanted to reply to an urgent message.","options":["checking","to check","check","to checking"],"answer":1,"explanation":"Stop + to-infinitive means pause one activity in order to do another."},
{"id":"ti-005","topic":"To vs. -ing","level":"medium","q":"I tried ___ my computer, but it didn't work.","options":["restarting","to restart","restart","to restarting"],"answer":1,"explanation":"Try + to-infinitive means make an attempt to do something."},
{"id":"ti-006","topic":"To vs. -ing","level":"medium","q":"The computer was slow, so I tried ___ it.","options":["to restart","restarting","restart","to restarting"],"answer":1,"explanation":"Try + -ing suggests experimenting with a possible solution."},
{"id":"ti-007","topic":"To vs. -ing","level":"hard","q":"She regrets ___ her previous job because she really enjoyed working there.","options":["to leave","leaving","leave","to leaving"],"answer":1,"explanation":"Regret + -ing refers to feeling sorry about something already done."},
{"id":"ti-008","topic":"To vs. -ing","level":"hard","q":"We regret ___ you that the meeting has been cancelled.","options":["informing","to inform","inform","to informing"],"answer":1,"explanation":"Regret + to-infinitive is used in formal notices when announcing unpleasant information."},
{"id":"ti-009","topic":"To vs. -ing","level":"medium","q":"I remember ___ this issue with my manager last year.","options":["to discuss","discussing","discuss","to discussing"],"answer":1,"explanation":"Remember + -ing refers to remembering a past experience."},
{"id":"ti-010","topic":"To vs. -ing","level":"hard","q":"She went on ___ about the problem for another twenty minutes.","options":["to talk","talking","talk","to talking"],"answer":1,"explanation":"Go on + -ing means continue the same activity."},
{"id":"ti-011","topic":"To vs. -ing","level":"easy","q":"I enjoy ___ new languages.","options":["to learn","learning","learn","to learning"],"answer":1,"explanation":"Enjoy is followed by the -ing form."},
{"id":"ti-012","topic":"To vs. -ing","level":"easy","q":"She decided ___ her job last month.","options":["quitting","quit","to quitting","to quit"],"answer":3,"explanation":"Decide is followed by a to-infinitive."},
{"id":"ti-013","topic":"To vs. -ing","level":"easy","q":"We need ___ the report by Friday.","options":["to finish","finishing","finish","to finishing"],"answer":0,"explanation":"Need is followed by a to-infinitive when something has to be done."},
{"id":"ti-014","topic":"To vs. -ing","level":"easy","q":"He avoids ___ meetings that are not necessary.","options":["to attend","attend","attending","to attending"],"answer":2,"explanation":"Avoid is followed by the -ing form."},
{"id":"ti-015","topic":"To vs. -ing","level":"easy","q":"They agreed ___ the deadline.","options":["to extend","extending","extend","to extending"],"answer":0,"explanation":"Agree is followed by a to-infinitive."},
{"id":"ti-016","topic":"To vs. -ing","level":"easy","q":"I'm looking forward to ___ you next week.","options":["meet","meeting","to meet","met"],"answer":1,"explanation":"In 'look forward to', the word to is a preposition, so it is followed by a noun or the -ing form."},
{"id":"ti-017","topic":"To vs. -ing","level":"easy","q":"She suggested ___ the meeting to Thursday.","options":["to move","move","moving","to moving"],"answer":2,"explanation":"Suggest is followed by the -ing form."},
{"id":"ti-018","topic":"To vs. -ing","level":"easy","q":"I can't afford ___ a new laptop right now.","options":["buying","buy","to buying","to buy"],"answer":3,"explanation":"Afford is followed by a to-infinitive."},
{"id":"ti-019","topic":"To vs. -ing","level":"medium","q":"I'll never forget ___ the CEO for the first time.","options":["meeting","to meet","meet","to meeting"],"answer":0,"explanation":"Forget + -ing refers to a memory of a past event. It is often used with never."},
{"id":"ti-020","topic":"To vs. -ing","level":"medium","q":"Don't forget ___ off the lights when you leave.","options":["to turn","turning","turn","to turning"],"answer":0,"explanation":"Forget + to-infinitive means you fail to do something you needed to do.","accept":["to turn","to switch"]},
{"id":"ti-021","topic":"To vs. -ing","level":"medium","q":"He's used to ___ up early because of his long commute.","options":["wake","waking","to wake","woke"],"answer":1,"explanation":"Be used to means 'be accustomed to'. Here to is a preposition, so it is followed by the -ing form."},
{"id":"ti-022","topic":"To vs. -ing","level":"medium","q":"We stopped ___ at a café because we were hungry.","options":["eating","eat","to eat","to eating"],"answer":2,"explanation":"Stop + to-infinitive gives the purpose of stopping: we stopped in order to eat."},
{"id":"ti-023","topic":"To vs. -ing","level":"medium","q":"She objects to ___ overtime without extra pay.","options":["work","to work","worked","working"],"answer":3,"explanation":"In 'object to', the word to is a preposition, so it is followed by the -ing form."},
{"id":"ti-024","topic":"To vs. -ing","level":"hard","q":"He joined the firm as an intern and went on ___ its managing director.","options":["becoming","become","to becoming","to become"],"answer":3,"explanation":"Go on + to-infinitive means to do something new after finishing something else."},
{"id":"ti-025","topic":"To vs. -ing","level":"hard","q":"I deeply regret ___ my colleague's advice; the project failed because of it.","options":["to ignore","ignoring","ignore","to ignoring"],"answer":1,"explanation":"Regret + -ing expresses regret about something you did in the past."},
{"id":"ti-026","topic":"To vs. -ing","level":"hard","q":"The proposal is worth ___ seriously.","options":["to consider","consider","considering","to considering"],"answer":2,"explanation":"Be worth is followed by the -ing form."},
{"id":"ti-027","topic":"To vs. -ing","level":"hard","q":"She isn't accustomed ___ in front of large audiences.","options":["to speaking","to speak","speaking","for speaking"],"answer":0,"explanation":"Be accustomed to is followed by -ing, because to is a preposition here."},
{"id":"ti-028","topic":"To vs. -ing","level":"hard","q":"I can't help ___ that the deadline is unrealistic.","options":["to feel","feeling","feel","to feeling"],"answer":1,"explanation":"Can't help + -ing means you cannot stop yourself from doing something."},
{"id":"ti-029","topic":"To vs. -ing","level":"hard","q":"He claims ___ the data before sending the report.","options":["checking","to checking","to have checked","check"],"answer":2,"explanation":"Claim is followed by a to-infinitive. Use the perfect infinitive (to have + past participle) for an earlier action."},
{"id":"ti-030","topic":"To vs. -ing","level":"hard","q":"I didn't mean ___ you; it was an accident.","options":["upsetting","upset","to upsetting","to upset"],"answer":3,"explanation":"Mean + to-infinitive means 'intend to'. (Mean + -ing means 'involve'.)"},
{"id":"ap-001","topic":"Active & Passive Voice","level":"easy","q":"The HR team ___ the salary structure last year.","options":["reviewed","was reviewed","is reviewed","has reviewed"],"answer":0,"explanation":"The subject performs the action, so the sentence is active."},
{"id":"ap-002","topic":"Active & Passive Voice","level":"easy","q":"The salary structure ___ by the HR team last year.","options":["reviewed","was reviewed","has reviewed","is reviewing"],"answer":1,"explanation":"The subject receives the action, so use the passive: was + past participle."},
{"id":"ap-003","topic":"Active & Passive Voice","level":"easy","q":"The report ___ tomorrow.","options":["will publish","will be published","is publishing","published"],"answer":1,"explanation":"For a future passive, use will be + past participle."},
{"id":"ap-004","topic":"Active & Passive Voice","level":"medium","q":"They have updated the policy.","options":["The policy has updated.","The policy has been updated.","The policy was updating.","The policy is updated by them."],"answer":1,"explanation":"Present perfect passive = has/have been + past participle.","w":{"q":"Rewrite in the passive voice: They have updated the policy.","accept":["The policy has been updated.","The policy has been updated by them."]}},
{"id":"ap-005","topic":"Active & Passive Voice","level":"medium","q":"People speak English in many countries.","options":["English is spoken in many countries.","English speaks in many countries.","English was spoken in many countries.","English has spoken in many countries."],"answer":0,"explanation":"Present simple passive = am/is/are + past participle.","w":{"q":"Rewrite in the passive voice: People speak English in many countries.","accept":["English is spoken in many countries.","English is spoken in many countries by people."]}},
{"id":"ap-006","topic":"Active & Passive Voice","level":"hard","q":"Someone is checking the figures right now.","options":["The figures are checked right now.","The figures are being checked right now.","The figures were checked right now.","The figures have been checking right now."],"answer":1,"explanation":"Present continuous passive = am/is/are being + past participle.","w":{"q":"Rewrite in the passive voice: Someone is checking the figures right now.","accept":["The figures are being checked right now.","The figures are being checked by someone right now."]}},
{"id":"ap-007","topic":"Active & Passive Voice","level":"hard","q":"The company had completed the project before the audit.","options":["The project had completed before the audit.","The project had been completed before the audit.","The project was completing before the audit.","The project has been completed before the audit."],"answer":1,"explanation":"Past perfect passive = had been + past participle.","w":{"q":"Rewrite in the passive voice: The company had completed the project before the audit.","accept":["The project had been completed before the audit.","The project had been completed by the company before the audit."]}},
{"id":"ap-008","topic":"Active & Passive Voice","level":"easy","q":"Which sentence is active?","options":["The contract was signed yesterday.","The results are being reviewed.","The manager approved the proposal.","The proposal has been approved."],"answer":2,"explanation":"In the active sentence, the subject 'the manager' performs the action 'approved'.","w":{"q":"Rewrite in the active voice: The proposal was approved by the manager.","accept":["The manager approved the proposal."]}},
{"id":"ap-009","topic":"Active & Passive Voice","level":"medium","q":"The committee will assess all applications.","options":["All applications will assess by the committee.","All applications will be assessed by the committee.","All applications are assessing by the committee.","All applications were assessed by the committee."],"answer":1,"explanation":"Future passive = will be + past participle.","w":{"q":"Rewrite in the passive voice: The committee will assess all applications.","accept":["All applications will be assessed by the committee.","All applications will be assessed."]}},
{"id":"ap-010","topic":"Active & Passive Voice","level":"easy","q":"Which sentence is passive?","options":["The analyst prepared the report.","The client requested changes.","The report was prepared by the analyst.","The team discussed the findings."],"answer":2,"explanation":"'The report' receives the action, shown by was + past participle.","w":{"q":"Rewrite in the passive voice: The analyst prepared the report.","accept":["The report was prepared by the analyst.","The report was prepared."]}},
{"id":"ap-011","topic":"Active & Passive Voice","level":"easy","q":"The email ___ by the assistant yesterday.","options":["sent","is sent","has sent","was sent"],"answer":3,"explanation":"Past simple passive: was/were + past participle."},
{"id":"ap-012","topic":"Active & Passive Voice","level":"easy","q":"English ___ all over the world.","options":["speaks","is spoken","spoke","is speaking"],"answer":1,"explanation":"Present simple passive: am/is/are + past participle."},
{"id":"ap-013","topic":"Active & Passive Voice","level":"easy","q":"These products ___ in Brazil.","options":["make","are made","is made","made"],"answer":1,"explanation":"Present simple passive with a plural subject: are + past participle."},
{"id":"ap-014","topic":"Active & Passive Voice","level":"easy","q":"The windows ___ every week.","options":["are cleaned","clean","are cleaning","cleaned"],"answer":0,"explanation":"Present simple passive: are + past participle."},
{"id":"ap-015","topic":"Active & Passive Voice","level":"easy","q":"My bag ___ at the airport last week.","options":["stole","has stolen","is stolen","was stolen"],"answer":3,"explanation":"Past simple passive: was + past participle. We use the passive when the subject receives the action."},
{"id":"ap-016","topic":"Active & Passive Voice","level":"medium","q":"Choose the correct passive form: The manager is writing the report.","options":["The report is written by the manager.","The report is being written by the manager.","The report was being written by the manager.","The report has been written by the manager."],"answer":1,"explanation":"Present continuous passive: am/is/are + being + past participle.","w":{"q":"Rewrite in the passive voice: The manager is writing the report.","accept":["The report is being written by the manager.","The report is being written."]}},
{"id":"ap-017","topic":"Active & Passive Voice","level":"medium","q":"The contract must ___ by both parties before Friday.","options":["sign","signed","be signed","be signing"],"answer":2,"explanation":"Modal passive: modal + be + past participle."},
{"id":"ap-018","topic":"Active & Passive Voice","level":"medium","q":"Choose the correct passive form: They didn't invite me to the meeting.","options":["I wasn't invited to the meeting.","I wasn't invite to the meeting.","I didn't invited to the meeting.","I haven't invited to the meeting."],"answer":0,"explanation":"Negative past simple passive: wasn't/weren't + past participle.","w":{"q":"Rewrite in the passive voice, starting with 'I': They didn't invite me to the meeting.","accept":["I wasn't invited to the meeting.","I wasn't invited to the meeting by them."]}},
{"id":"ap-019","topic":"Active & Passive Voice","level":"medium","q":"The documents ___ by the time we arrived.","options":["had been signed","have been signed","had signed","were signing"],"answer":0,"explanation":"Past perfect passive: had been + past participle, for an action completed before another past moment."},
{"id":"ap-020","topic":"Active & Passive Voice","level":"medium","q":"A new policy is currently ___ by the board.","options":["being discussed","discussed","discussing","been discussed"],"answer":0,"explanation":"Present continuous passive: am/is/are + being + past participle."},
{"id":"ap-021","topic":"Active & Passive Voice","level":"medium","q":"Employees ___ to submit their timesheets by Friday.","options":["require","are requiring","are required","required"],"answer":2,"explanation":"The passive of 'require' is are required to + verb."},
{"id":"ap-022","topic":"Active & Passive Voice","level":"medium","q":"The results ___ yet.","options":["haven't announced","didn't announced","aren't announcing","haven't been announced"],"answer":3,"explanation":"Present perfect passive: has/have been + past participle."},
{"id":"ap-023","topic":"Active & Passive Voice","level":"hard","q":"The minister ___ to have resigned.","options":["believes","is believed","is believing","was believing"],"answer":1,"explanation":"Impersonal passive: is believed/said/thought + to-infinitive. Use to have + past participle for an earlier event.","accept":["is believed","is thought","is said","is reported","is understood"]},
{"id":"ap-024","topic":"Active & Passive Voice","level":"hard","q":"The prototype ___ by the time the investors visit next week.","options":["will have tested","has been tested","will be testing","will have been tested"],"answer":3,"explanation":"Future perfect passive: will have been + past participle, for an action completed before a future moment."},
{"id":"ap-025","topic":"Active & Passive Voice","level":"hard","q":"He doesn't like ___ what to do.","options":["telling","being told","tell","to telling"],"answer":1,"explanation":"After like, the passive -ing form is being + past participle: he doesn't like it when people tell him what to do.","accept":["being told","to be told"]},
{"id":"ap-026","topic":"Active & Passive Voice","level":"hard","q":"I had my laptop ___ last week.","options":["repair","repairing","repaired","to repair"],"answer":2,"explanation":"Causative: have + object + past participle means someone else did the action for you.","accept":["repaired","fixed","serviced"]},
{"id":"ap-027","topic":"Active & Passive Voice","level":"hard","q":"The report needs ___ before it is sent.","options":["to check","to be checking","to be checked","be checked"],"answer":2,"explanation":"Need + to be + past participle expresses a passive necessity: someone must check the report.","accept":["to be checked","to be reviewed","to be proofread","to be approved"]},
{"id":"ap-028","topic":"Active & Passive Voice","level":"hard","q":"The company is said ___ the highest salaries in the sector.","options":["to offer","offering","offer","to offering"],"answer":0,"explanation":"Is said + to-infinitive is an impersonal passive structure.","accept":["to offer","to pay"]},
{"id":"ap-029","topic":"Active & Passive Voice","level":"hard","q":"Choose the correct passive form: The courier delivered the package yesterday.","options":["The package was been delivered yesterday.","The package delivered yesterday.","The package has delivered yesterday.","The package was delivered yesterday."],"answer":3,"explanation":"Past simple passive: was + past participle. The agent (the courier) can be left out.","w":{"q":"Rewrite in the passive voice: The courier delivered the package yesterday.","accept":["The package was delivered yesterday.","The package was delivered by the courier yesterday.","The package was delivered by the courier."]}},
{"id":"ap-030","topic":"Active & Passive Voice","level":"hard","q":"Several staff members ___ during the restructuring last year.","options":["made redundant","have made redundant","were made redundant","were making redundant"],"answer":2,"explanation":"Past simple passive: were + past participle. 'Made redundant' is the standard British expression for losing a job that is no longer needed.","accept":["were made redundant","were laid off","were let go"]},
{"id":"cd-001","topic":"Conditionals","level":"easy","q":"If you heat ice, it ___.","options":["melts","will melt","would melt","melted"],"answer":0,"explanation":"Zero conditional describes general truths: if + present simple, present simple."},
{"id":"cd-002","topic":"Conditionals","level":"easy","q":"If I finish early, I ___ you tonight.","options":["call","would call","will call","called"],"answer":2,"explanation":"First conditional uses if + present simple and will + base verb for a real future possibility."},
{"id":"cd-003","topic":"Conditionals","level":"medium","q":"If I had more time, I ___ another language.","options":["will learn","would learn","learned","would have learned"],"answer":1,"explanation":"Second conditional describes an unreal or unlikely present/future situation: if + past, would + base verb."},
{"id":"cd-004","topic":"Conditionals","level":"medium","q":"If she had studied harder, she ___ the exam.","options":["would pass","will pass","would have passed","passed"],"answer":2,"explanation":"Third conditional refers to an unreal past result: if + past perfect, would have + past participle."},
{"id":"cd-005","topic":"Conditionals","level":"hard","q":"If I had accepted that job, I ___ in London now.","options":["would live","would have lived","will live","lived"],"answer":0,"explanation":"Mixed conditional: an unreal past condition has a present result.","accept":["would live","would be living"]},
{"id":"cd-006","topic":"Conditionals","level":"hard","q":"If I weren't so busy, I ___ the meeting yesterday.","options":["would attend","would have attended","will attend","attended"],"answer":1,"explanation":"Mixed conditional: an unreal present condition explains an unreal past result."},
{"id":"cd-007","topic":"Conditionals","level":"medium","q":"If companies invest in training, employees usually ___ more confident.","options":["become","will become","would become","became"],"answer":0,"explanation":"This is a general relationship, so the zero conditional is appropriate."},
{"id":"cd-008","topic":"Conditionals","level":"easy","q":"If the client agrees, we ___ the project next month.","options":["would start","started","will start","would have started"],"answer":2,"explanation":"A possible future condition takes first conditional form."},
{"id":"cd-009","topic":"Conditionals","level":"easy","q":"If I were you, I ___ the offer carefully.","options":["will consider","would consider","considered","would have considered"],"answer":1,"explanation":"'If I were you' is a common second-conditional form for advice."},
{"id":"cd-010","topic":"Conditionals","level":"hard","q":"If they had invested earlier, they ___ the technology now.","options":["would own","would have owned","will own","owned"],"answer":0,"explanation":"The past condition ('had invested') leads to a present result ('would own')."},
{"id":"cd-011","topic":"Conditionals","level":"easy","q":"If it rains tomorrow, we ___ the picnic.","options":["would cancel","cancelled","would have cancelled","will cancel"],"answer":3,"explanation":"First conditional: if + present simple, will + base verb, for a real future possibility."},
{"id":"cd-012","topic":"Conditionals","level":"easy","q":"If you ___ water to 100°C, it boils.","options":["will heat","heated","heat","would heat"],"answer":2,"explanation":"Zero conditional: if + present simple, present simple, for general truths."},
{"id":"cd-013","topic":"Conditionals","level":"easy","q":"If I ___ rich, I would travel the world.","options":["am","were","will be","would be"],"answer":1,"explanation":"Second conditional: if + past simple, would + verb. With be, were is used for all persons in formal English.","accept":["were","was"]},
{"id":"cd-014","topic":"Conditionals","level":"easy","q":"If she calls, I ___ her the news.","options":["would tell","told","would have told","will tell"],"answer":3,"explanation":"First conditional: if + present simple, will + base verb."},
{"id":"cd-015","topic":"Conditionals","level":"easy","q":"If we ___ earlier, we wouldn't have missed the train.","options":["had left","left","would leave","leave"],"answer":0,"explanation":"Third conditional: if + past perfect, would have + past participle."},
{"id":"cd-016","topic":"Conditionals","level":"easy","q":"If you mix red and blue, you ___ purple.","options":["would get","got","get","would have got"],"answer":2,"explanation":"Zero conditional: if + present simple, present simple, for facts that are always true.","accept":["get","will get"]},
{"id":"cd-017","topic":"Conditionals","level":"medium","q":"I wouldn't accept that offer if I ___ you.","options":["am","were","would be","had been"],"answer":1,"explanation":"Second conditional advice: if I were you, I would...","accept":["were","was"]},
{"id":"cd-018","topic":"Conditionals","level":"medium","q":"Unless you ___ the deadline, we will lose the contract.","options":["will meet","met","meet","would meet"],"answer":2,"explanation":"Unless means 'if not' and is followed by the present simple in a first conditional."},
{"id":"cd-019","topic":"Conditionals","level":"medium","q":"If the project ___ on time, the client would have been happier.","options":["was completed","had been completed","would be completed","is completed"],"answer":1,"explanation":"Third conditional: if + past perfect (passive here), would have + past participle.","accept":["had been completed","had been delivered","had been finished"]},
{"id":"cd-020","topic":"Conditionals","level":"medium","q":"What ___ if the server crashed during the launch?","options":["will you do","would you have done","would you do","did you do"],"answer":2,"explanation":"Second conditional question: what would + subject + verb if + past simple."},
{"id":"cd-021","topic":"Conditionals","level":"medium","q":"As long as you ___ the rules, you can use the equipment.","options":["will follow","would follow","followed","follow"],"answer":3,"explanation":"As long as means 'if' and is followed by the present simple in a real condition."},
{"id":"cd-022","topic":"Conditionals","level":"medium","q":"If I ___ the email earlier, I would have replied immediately.","options":["had seen","saw","would see","have seen"],"answer":0,"explanation":"Third conditional: if + past perfect, would have + past participle."},
{"id":"cd-023","topic":"Conditionals","level":"medium","q":"She would help us if she ___ time.","options":["had","has","will have","would have"],"answer":0,"explanation":"Second conditional: if + past simple, would + base verb."},
{"id":"cd-024","topic":"Conditionals","level":"hard","q":"Had I known about the delay, I ___ the client.","options":["would call","would have called","will call","called"],"answer":1,"explanation":"Inverted third conditional: Had + subject + past participle replaces if + past perfect."},
{"id":"cd-025","topic":"Conditionals","level":"hard","q":"___ you need further assistance, please contact our support team.","options":["Would","Were","Should","Had"],"answer":2,"explanation":"Should + subject (inversion) is a formal way to say 'if you need'."},
{"id":"cd-026","topic":"Conditionals","level":"hard","q":"If it ___ for her support, the project would have failed.","options":["wasn't","hadn't been","weren't","wouldn't be"],"answer":1,"explanation":"If it hadn't been for + noun means 'without': a third conditional structure."},
{"id":"cd-027","topic":"Conditionals","level":"hard","q":"If only we ___ the warning signs earlier!","options":["had noticed","noticed","would notice","have noticed"],"answer":0,"explanation":"If only + past perfect expresses regret about the past."},
{"id":"cd-028","topic":"Conditionals","level":"hard","q":"If we hadn't merged with that firm, we ___ the market leader today.","options":["would be","would have been","will be","are"],"answer":0,"explanation":"Mixed conditional: a past condition (past perfect) with a present result (would + base verb)."},
{"id":"cd-029","topic":"Conditionals","level":"hard","q":"If the supplier were to increase prices, we ___ to switch.","options":["will have","had","would had","would have"],"answer":3,"explanation":"If + were to + verb is a formal way to talk about an unlikely future situation. The result uses would (would have to switch)."},
{"id":"cd-030","topic":"Conditionals","level":"hard","q":"Provided that all the paperwork ___ by Monday, your application will be processed.","options":["will be submitted","was submitted","would be submitted","is submitted"],"answer":3,"explanation":"Provided that means 'if' and is followed by the present simple in a real condition.","accept":["is submitted","is received","is handed in","is completed"]},
{"id":"rp-001","topic":"Relative Pronouns","level":"easy","q":"The analyst ___ prepared the report is on leave today.","options":["which","who","where","whose"],"answer":1,"explanation":"Use who for people when it is the subject of a defining relative clause.","accept":["who","that"]},
{"id":"rp-002","topic":"Relative Pronouns","level":"easy","q":"The report ___ you sent was very clear.","options":["who","where","which","whose"],"answer":2,"explanation":"Use which for things in a defining relative clause.","accept":["which","that"]},
{"id":"rp-003","topic":"Relative Pronouns","level":"medium","q":"The manager ___ team won the award thanked everyone.","options":["who","which","whose","whom"],"answer":2,"explanation":"Whose shows possession and can refer to people or things."},
{"id":"rp-004","topic":"Relative Pronouns","level":"hard","q":"The colleague to ___ I spoke yesterday is from Finance.","options":["who","whom","which","that"],"answer":1,"explanation":"After a preposition in formal English, whom is used for a person as the object."},
{"id":"rp-005","topic":"Relative Pronouns","level":"medium","q":"The company ___ I work for is expanding.","options":["who","where","which","whose"],"answer":2,"explanation":"Which can refer to a company; 'that' would also be possible in this defining clause.","accept":["which","that"]},
{"id":"rp-006","topic":"Relative Pronouns","level":"medium","q":"The office ___ we had the meeting was very small.","options":["who","where","whose","whom"],"answer":1,"explanation":"Where refers to a place and means 'in/at which'.","accept":["where","in which"]},
{"id":"rp-007","topic":"Relative Pronouns","level":"easy","q":"Which sentence is correct?","options":["The person which called me was helpful.","The person who called me was helpful.","The person where called me was helpful.","The person whose called me was helpful."],"answer":1,"explanation":"Who is used for people as the subject of the relative clause.","w":{"q":"Complete with the correct relative pronoun: The person ___ called me was helpful.","accept":["who","that"]}},
{"id":"rp-008","topic":"Relative Pronouns","level":"hard","q":"The policy, ___ was introduced last year, has been updated.","options":["that","who","which","whom"],"answer":2,"explanation":"In a non-defining relative clause set off by commas, use which for things, not that."},
{"id":"rp-009","topic":"Relative Pronouns","level":"hard","q":"The consultant ___ we hired has extensive experience.","options":["whom","where","which","whose"],"answer":0,"explanation":"Whom is grammatically possible as the object of 'hired'; in everyday English, who or that is also common.","accept":["whom","who","that"]},
{"id":"rp-010","topic":"Relative Pronouns","level":"medium","q":"The employees ___ contracts expire this month will be contacted.","options":["who","whose","which","whom"],"answer":1,"explanation":"Whose indicates possession: the contracts belong to the employees."},
{"id":"rp-011","topic":"Relative Pronouns","level":"easy","q":"The woman ___ lives next door is a doctor.","options":["which","whose","who","where"],"answer":2,"explanation":"Use who for people as the subject of the relative clause.","accept":["who","that"]},
{"id":"rp-012","topic":"Relative Pronouns","level":"easy","q":"This is the book ___ I told you about.","options":["that","who","whose","where"],"answer":0,"explanation":"That (or which) introduces a defining clause about things.","accept":["that","which"]},
{"id":"rp-013","topic":"Relative Pronouns","level":"easy","q":"That's the restaurant ___ we had dinner.","options":["which","who","where","whose"],"answer":2,"explanation":"Where refers to a place. Without a preposition, which cannot be used here.","accept":["where","at which"]},
{"id":"rp-014","topic":"Relative Pronouns","level":"easy","q":"I know a man ___ brother is a famous actor.","options":["who","which","whom","whose"],"answer":3,"explanation":"Use whose to show possession."},
{"id":"rp-015","topic":"Relative Pronouns","level":"easy","q":"The car ___ I bought last year is already broken.","options":["which","who","whose","where"],"answer":0,"explanation":"Use which (or that) for things.","accept":["which","that"]},
{"id":"rp-016","topic":"Relative Pronouns","level":"easy","q":"She is the person ___ helped me yesterday.","options":["whose","which","who","where"],"answer":2,"explanation":"Use who (or that) for people as the subject.","accept":["who","that"]},
{"id":"rp-017","topic":"Relative Pronouns","level":"easy","q":"Brazil is the country ___ I was born.","options":["who","where","whose","whom"],"answer":1,"explanation":"Where refers to a place.","accept":["where","in which"]},
{"id":"rp-018","topic":"Relative Pronouns","level":"medium","q":"The report, ___ was written by our intern, impressed everyone.","options":["that","who","which","whose"],"answer":2,"explanation":"In a non-defining clause (between commas), use which, not that."},
{"id":"rp-019","topic":"Relative Pronouns","level":"medium","q":"The candidate ___ we interviewed first was the strongest.","options":["whom","whose","where","which"],"answer":0,"explanation":"Whom is the formal object form for people. Who or that are common in everyday use.","accept":["whom","who","that"]},
{"id":"rp-020","topic":"Relative Pronouns","level":"medium","q":"She works for a company ___ headquarters are in Madrid.","options":["which","who","whom","whose"],"answer":3,"explanation":"Whose shows possession, and it can be used for companies as well as people."},
{"id":"rp-021","topic":"Relative Pronouns","level":"medium","q":"That is the reason ___ I left.","options":["who","why","whose","whom"],"answer":1,"explanation":"Why follows the noun reason.","accept":["why","that"]},
{"id":"rp-022","topic":"Relative Pronouns","level":"medium","q":"Mr Silva, to ___ I spoke yesterday, is the new director.","options":["who","which","whose","whom"],"answer":3,"explanation":"After a preposition, use whom for people."},
{"id":"rp-023","topic":"Relative Pronouns","level":"medium","q":"Everything ___ he said was true.","options":["that","what","who","whose"],"answer":0,"explanation":"After words like everything, all or nothing, use that."},
{"id":"rp-024","topic":"Relative Pronouns","level":"hard","q":"The proposal, the details of ___ were leaked, was withdrawn.","options":["which","whom","whose","that"],"answer":0,"explanation":"After 'of' referring to things, use which: the details of which."},
{"id":"rp-025","topic":"Relative Pronouns","level":"hard","q":"He has three sisters, two of ___ live abroad.","options":["who","which","whose","whom"],"answer":3,"explanation":"After a quantifier + of, use whom for people."},
{"id":"rp-026","topic":"Relative Pronouns","level":"hard","q":"The documents, most of ___ were confidential, disappeared.","options":["whom","which","who","those"],"answer":1,"explanation":"After a quantifier + of, use which for things."},
{"id":"rp-027","topic":"Relative Pronouns","level":"hard","q":"She passed the exam, ___ surprised everyone.","options":["that","what","who","which"],"answer":3,"explanation":"Which can refer to a whole clause. That cannot be used after a comma."},
{"id":"rp-028","topic":"Relative Pronouns","level":"hard","q":"This is the manager ___ I believe made the decision.","options":["whom","who","which","whose"],"answer":1,"explanation":"Who is the subject of 'made'. The phrase 'I believe' is extra and doesn't change that.","accept":["who","that"]},
{"id":"rp-029","topic":"Relative Pronouns","level":"hard","q":"The city in ___ she grew up has changed dramatically.","options":["that","which","where","whom"],"answer":1,"explanation":"After a preposition, use which for things: in which."},
{"id":"rp-030","topic":"Relative Pronouns","level":"hard","q":"I'll give the job to ___ has the most experience.","options":["whomever","whichever","whoever","whatever"],"answer":2,"explanation":"Whoever means 'the person who' and is the subject of 'has'.","accept":["whoever","anyone who","the person who"]},
{"id":"ioa-001","topic":"In vs. On vs. At","level":"easy","q":"I was born ___ Brazil.","options":["at","on","in","to"],"answer":2,"explanation":"Use in with countries, cities, and other larger areas."},
{"id":"ioa-002","topic":"In vs. On vs. At","level":"easy","q":"The meeting is ___ Monday morning.","options":["in","on","at","by"],"answer":1,"explanation":"Use on with days and dates, including specific days such as Monday morning."},
{"id":"ioa-003","topic":"In vs. On vs. At","level":"easy","q":"The meeting starts ___ 9 a.m.","options":["in","on","at","by"],"answer":2,"explanation":"Use at with a specific clock time."},
{"id":"ioa-004","topic":"In vs. On vs. At","level":"easy","q":"She works ___ London.","options":["at","on","in","by"],"answer":2,"explanation":"Use in with cities."},
{"id":"ioa-005","topic":"In vs. On vs. At","level":"easy","q":"The report is ___ the table.","options":["in","on","at","to"],"answer":1,"explanation":"Use on when something is physically positioned on a surface."},
{"id":"ioa-006","topic":"In vs. On vs. At","level":"medium","q":"We met ___ the entrance.","options":["in","on","at","to"],"answer":2,"explanation":"At is commonly used for a specific point or location."},
{"id":"ioa-007","topic":"In vs. On vs. At","level":"easy","q":"I usually study ___ the evening.","options":["at","on","in","by"],"answer":2,"explanation":"Use in with parts of the day: in the morning, in the afternoon, in the evening."},
{"id":"ioa-008","topic":"In vs. On vs. At","level":"easy","q":"The company was founded ___ 2012.","options":["at","on","in","from"],"answer":2,"explanation":"Use in with years."},
{"id":"ioa-009","topic":"In vs. On vs. At","level":"easy","q":"I'll see you ___ Friday.","options":["in","on","at","to"],"answer":1,"explanation":"Use on with days of the week."},
{"id":"ioa-010","topic":"In vs. On vs. At","level":"medium","q":"He arrived ___ the airport at 6:30.","options":["in","on","at","to"],"answer":2,"explanation":"Use at for a specific point such as an airport when focusing on the location."},
{"id":"ioa-011","topic":"In vs. On vs. At","level":"easy","q":"I usually wake up ___ 7 a.m.","options":["at","in","on","to"],"answer":0,"explanation":"Use at with specific clock times."},
{"id":"ioa-012","topic":"In vs. On vs. At","level":"easy","q":"My birthday is ___ July.","options":["on","in","at","by"],"answer":1,"explanation":"Use in with months."},
{"id":"ioa-013","topic":"In vs. On vs. At","level":"medium","q":"We have a team lunch ___ the 15th of March.","options":["in","at","on","by"],"answer":2,"explanation":"Use on with specific dates."},
{"id":"ioa-014","topic":"In vs. On vs. At","level":"medium","q":"She lives ___ 24 Maple Street.","options":["in","at","on","by"],"answer":1,"explanation":"Use at with a full street address that includes a number."},
{"id":"ioa-015","topic":"In vs. On vs. At","level":"medium","q":"He was born ___ the 1990s.","options":["on","in","at","by"],"answer":1,"explanation":"Use in with decades, years and centuries."},
{"id":"ioa-016","topic":"In vs. On vs. At","level":"medium","q":"The seminar takes place ___ the third floor.","options":["in","at","on","to"],"answer":2,"explanation":"Use on with floors of a building."},
{"id":"ioa-017","topic":"In vs. On vs. At","level":"medium","q":"She stayed ___ home all day.","options":["in","on","at","to"],"answer":2,"explanation":"At home is a fixed expression."},
{"id":"ioa-018","topic":"In vs. On vs. At","level":"medium","q":"There is a typo ___ page 12.","options":["in","at","on","to"],"answer":2,"explanation":"Use on with pages."},
{"id":"ioa-019","topic":"In vs. On vs. At","level":"medium","q":"I read about it ___ the newspaper this morning.","options":["on","at","by","in"],"answer":3,"explanation":"We say in the newspaper, but on the news or on TV."},
{"id":"ioa-020","topic":"In vs. On vs. At","level":"medium","q":"I saw the advert ___ TV.","options":["on","in","at","by"],"answer":0,"explanation":"Use on with TV, radio and the internet."},
{"id":"ioa-021","topic":"In vs. On vs. At","level":"hard","q":"She is ___ charge of the new department.","options":["at","on","in","by"],"answer":2,"explanation":"In charge of is a fixed expression."},
{"id":"ioa-022","topic":"In vs. On vs. At","level":"hard","q":"He is currently ___ a business trip in Tokyo.","options":["in","on","at","for"],"answer":1,"explanation":"We say on a business trip, on holiday, on vacation."},
{"id":"ioa-023","topic":"In vs. On vs. At","level":"hard","q":"The flight was ___ time despite the storm.","options":["in","at","by","on"],"answer":3,"explanation":"On time means 'at the planned time'."},
{"id":"ioa-024","topic":"In vs. On vs. At","level":"hard","q":"He is ___ his early thirties.","options":["on","at","by","in"],"answer":3,"explanation":"We use in with ages in decades: in his thirties, in her early forties."},
{"id":"ioa-025","topic":"In vs. On vs. At","level":"hard","q":"I'm ___ a meeting right now; can I call you back?","options":["in","on","at","to"],"answer":0,"explanation":"We say in a meeting."},
{"id":"ioa-026","topic":"In vs. On vs. At","level":"hard","q":"She is ___ leave until the 3rd of May.","options":["in","at","by","on"],"answer":3,"explanation":"On leave is a fixed expression."},
{"id":"ioa-027","topic":"In vs. On vs. At","level":"hard","q":"___ my opinion, the plan is too risky.","options":["On","At","By","In"],"answer":3,"explanation":"In my opinion is a fixed expression."},
{"id":"ioa-028","topic":"In vs. On vs. At","level":"hard","q":"The tickets go ___ sale on Monday.","options":["on","in","at","by"],"answer":0,"explanation":"On sale is a fixed expression."},
{"id":"ioa-029","topic":"In vs. On vs. At","level":"hard","q":"He's ___ the phone with a client.","options":["in","on","at","by"],"answer":1,"explanation":"We say on the phone."},
{"id":"ioa-030","topic":"In vs. On vs. At","level":"hard","q":"She felt ___ ease during the interview.","options":["at","in","on","by"],"answer":0,"explanation":"At ease is a fixed expression."},
{"id":"tf-001","topic":"To vs. For","level":"easy","q":"I sent the report ___ my manager.","options":["for","to","at","on"],"answer":1,"explanation":"Use to for the recipient or destination of something sent or given."},
{"id":"tf-002","topic":"To vs. For","level":"medium","q":"This tool is useful ___ analysing large datasets.","options":["to","for","at","on"],"answer":1,"explanation":"Use for + -ing to express purpose or function."},
{"id":"tf-003","topic":"To vs. For","level":"easy","q":"I went ___ London last weekend.","options":["for","to","at","in"],"answer":1,"explanation":"Use to with movement toward a destination."},
{"id":"tf-004","topic":"To vs. For","level":"easy","q":"This gift is ___ you.","options":["to","for","at","with"],"answer":1,"explanation":"Use for to indicate the intended recipient or beneficiary of a gift."},
{"id":"tf-005","topic":"To vs. For","level":"medium","q":"She explained the problem ___ me.","options":["for","to","at","on"],"answer":1,"explanation":"Explain takes to for the person who receives the explanation."},
{"id":"tf-006","topic":"To vs. For","level":"medium","q":"I bought a notebook ___ taking notes.","options":["to","for","at","on"],"answer":1,"explanation":"For + -ing can express purpose or intended use."},
{"id":"tf-007","topic":"To vs. For","level":"easy","q":"We need ___ improve the process.","options":["for","to","at","on"],"answer":1,"explanation":"Use to + base verb to express purpose after need in this structure."},
{"id":"tf-008","topic":"To vs. For","level":"easy","q":"This room is ___ meetings.","options":["to","for","at","on"],"answer":1,"explanation":"For can indicate intended use: a room for meetings."},
{"id":"tf-009","topic":"To vs. For","level":"easy","q":"She gave the documents ___ the client.","options":["for","to","at","on"],"answer":1,"explanation":"Use to for the recipient of something given."},
{"id":"tf-010","topic":"To vs. For","level":"easy","q":"I did it ___ my team.","options":["to","for","at","on"],"answer":1,"explanation":"Use for when someone benefits from an action or when you act on their behalf."},
{"id":"tf-011","topic":"To vs. For","level":"easy","q":"I called you ___ ask about the schedule.","options":["for","at","to","on"],"answer":2,"explanation":"Use to + verb to express purpose."},
{"id":"tf-012","topic":"To vs. For","level":"easy","q":"She made a cake ___ her sister.","options":["for","to","at","on"],"answer":0,"explanation":"Use for to show who benefits."},
{"id":"tf-013","topic":"To vs. For","level":"easy","q":"Welcome ___ our company!","options":["for","at","to","on"],"answer":2,"explanation":"Welcome is followed by to."},
{"id":"tf-014","topic":"To vs. For","level":"medium","q":"This software is designed ___ small businesses.","options":["to","for","at","on"],"answer":1,"explanation":"Use for before a noun to show the intended user or purpose."},
{"id":"tf-015","topic":"To vs. For","level":"medium","q":"I use this app ___ organise my tasks.","options":["for","to","at","on"],"answer":1,"explanation":"Use to + verb to express purpose."},
{"id":"tf-016","topic":"To vs. For","level":"medium","q":"I use this app ___ organising my tasks.","options":["to","at","on","for"],"answer":3,"explanation":"Use for + -ing to express purpose or function."},
{"id":"tf-017","topic":"To vs. For","level":"medium","q":"Thank you ___ your help.","options":["to","for","at","on"],"answer":1,"explanation":"We thank someone for something."},
{"id":"tf-018","topic":"To vs. For","level":"medium","q":"She is responsible ___ the budget.","options":["to","at","on","for"],"answer":3,"explanation":"Be responsible for something."},
{"id":"tf-019","topic":"To vs. For","level":"medium","q":"He apologised ___ the delay.","options":["for","to","at","on"],"answer":0,"explanation":"We apologise for something."},
{"id":"tf-020","topic":"To vs. For","level":"medium","q":"He is married ___ a lawyer.","options":["with","to","for","at"],"answer":1,"explanation":"Be married to someone."},
{"id":"tf-021","topic":"To vs. For","level":"hard","q":"The decision was made ___ the benefit of the whole team.","options":["to","at","for","on"],"answer":2,"explanation":"For the benefit of is a fixed expression."},
{"id":"tf-022","topic":"To vs. For","level":"hard","q":"He is known ___ his generosity.","options":["to","at","on","for"],"answer":3,"explanation":"Be known for something. (Known to means 'familiar to' a person.)"},
{"id":"tf-023","topic":"To vs. For","level":"hard","q":"I'm writing ___ apply for the position of analyst.","options":["for","at","on","to"],"answer":3,"explanation":"Use to + verb to express purpose."},
{"id":"tf-024","topic":"To vs. For","level":"hard","q":"She has a talent ___ languages.","options":["to","with","on","for"],"answer":3,"explanation":"We say a talent for something."},
{"id":"tf-025","topic":"To vs. For","level":"hard","q":"Listen ___ me carefully.","options":["to","for","at","on"],"answer":0,"explanation":"Listen to someone or something. (Listen for means 'try to hear'.)"},
{"id":"tf-026","topic":"To vs. For","level":"hard","q":"This is an excellent opportunity ___ our team to grow.","options":["for","to","at","on"],"answer":0,"explanation":"Opportunity for + person + to-infinitive."},
{"id":"tf-027","topic":"To vs. For","level":"hard","q":"He was sentenced ___ five years in prison.","options":["to","for","at","on"],"answer":0,"explanation":"We sentence someone to a punishment."},
{"id":"tf-028","topic":"To vs. For","level":"hard","q":"We are grateful ___ your support.","options":["to","for","at","on"],"answer":1,"explanation":"We are grateful for something, and grateful to someone."},
{"id":"tf-029","topic":"To vs. For","level":"hard","q":"It's too early ___ me to decide.","options":["to","at","for","on"],"answer":2,"explanation":"Too + adjective + for + person + to-infinitive."},
{"id":"tf-030","topic":"To vs. For","level":"hard","q":"She prepared ___ the interview for hours.","options":["to","at","for","on"],"answer":2,"explanation":"We prepare for an event."},
{"id":"mv-001","topic":"Modal Verbs","level":"easy","q":"You ___ park here. It's forbidden.","options":["don't have to","might","can","mustn't"],"answer":3,"explanation":"Mustn't expresses prohibition: it is not allowed.","accept":["mustn't","can't"]},
{"id":"mv-002","topic":"Modal Verbs","level":"easy","q":"I ___ swim when I was five.","options":["can","must","could","should"],"answer":2,"explanation":"Could is used for general ability in the past.","accept":["could","was able to"]},
{"id":"mv-003","topic":"Modal Verbs","level":"easy","q":"___ I borrow your pen, please?","options":["Must","Can","Will","Shall"],"answer":1,"explanation":"Can/Could/May I ...? is used to ask for permission.","accept":["Can","Could","May"]},
{"id":"mv-004","topic":"Modal Verbs","level":"easy","q":"You ___ see a doctor. You look very ill.","options":["should","can't","mustn't","needn't"],"answer":0,"explanation":"Should is used to give advice.","accept":["should","must","ought to","had better"]},
{"id":"mv-005","topic":"Modal Verbs","level":"easy","q":"She ___ speak three languages. She's very talented.","options":["should","would","can","ought"],"answer":2,"explanation":"Can expresses ability in the present.","accept":["can","is able to"]},
{"id":"mv-006","topic":"Modal Verbs","level":"easy","q":"We ___ wear a uniform at school. It's a rule.","options":["have to","might","can","would"],"answer":0,"explanation":"Have to (or must) expresses obligation.","accept":["have to","must"]},
{"id":"mv-007","topic":"Modal Verbs","level":"easy","q":"It's a holiday tomorrow, so we ___ get up early.","options":["mustn't","can't","must","don't have to"],"answer":3,"explanation":"Don't have to means something is not necessary. (Mustn't means it is forbidden.)","accept":["don't have to","needn't","don't need to"]},
{"id":"mv-008","topic":"Modal Verbs","level":"easy","q":"___ you help me with these bags? They're heavy.","options":["Must","Could","Should","Ought"],"answer":1,"explanation":"Could/Can/Would you ...? is used for polite requests.","accept":["Could","Can","Would","Will"]},
{"id":"mv-009","topic":"Modal Verbs","level":"easy","q":"I ___ finish this today, or I'll be in trouble.","options":["must","might","can't","needn't"],"answer":0,"explanation":"Must or have to expresses strong necessity.","accept":["must","have to","need to"]},
{"id":"mv-010","topic":"Modal Verbs","level":"easy","q":"We're not sure yet, but we ___ go to Spain this summer.","options":["mustn't","can't","needn't","might"],"answer":3,"explanation":"Might (or may/could) expresses a possibility.","accept":["might","may","could"]},
{"id":"mv-011","topic":"Modal Verbs","level":"medium","q":"You ___ have told me earlier! Now it's too late.","options":["must","may","should","can"],"answer":2,"explanation":"Should have + past participle criticises something that was not done in the past.","accept":["should","ought to","could"]},
{"id":"mv-012","topic":"Modal Verbs","level":"medium","q":"She ___ be at work; her car is outside.","options":["can't","needn't","mustn't","must"],"answer":3,"explanation":"Must expresses a logical deduction when you are almost certain."},
{"id":"mv-013","topic":"Modal Verbs","level":"medium","q":"You ___ have brought a gift. It wasn't necessary.","options":["needn't","mustn't","can't","wouldn't"],"answer":0,"explanation":"Needn't have + past participle means you did something that was not necessary.","accept":["needn't","need not"]},
{"id":"mv-014","topic":"Modal Verbs","level":"medium","q":"When I was a child, I ___ play outside until it got dark.","options":["would","should","must","might"],"answer":0,"explanation":"Would can describe repeated habits in the past (like used to).","accept":["would","used to"]},
{"id":"mv-015","topic":"Modal Verbs","level":"medium","q":"You ___ better take an umbrella. It looks like rain.","options":["would","had","should","must"],"answer":1,"explanation":"Had better + base verb gives strong advice about a specific situation."},
{"id":"mv-016","topic":"Modal Verbs","level":"medium","q":"I'm sorry, I ___ come to the meeting yesterday. I was ill.","options":["can't","couldn't","mustn't","needn't"],"answer":1,"explanation":"Couldn't expresses inability in the past.","accept":["couldn't","wasn't able to"]},
{"id":"mv-017","topic":"Modal Verbs","level":"medium","q":"Students ___ use calculators during the exam. It's allowed.","options":["mustn't","may","can't","won't"],"answer":1,"explanation":"May (or can) expresses permission.","accept":["may","can","are allowed to"]},
{"id":"mv-018","topic":"Modal Verbs","level":"medium","q":"He ___ to work late tonight, so he won't join us.","options":["must","can","has","should"],"answer":2,"explanation":"Have to expresses obligation; with he/she it becomes has to."},
{"id":"mv-019","topic":"Modal Verbs","level":"medium","q":"___ I carry your bags?","options":["Must","Do","Would","Shall"],"answer":3,"explanation":"Shall I ...? is used to offer help.","accept":["Shall","Can","Could","May"]},
{"id":"mv-020","topic":"Modal Verbs","level":"medium","q":"You ___ to apologise to her. It was your fault.","options":["ought","can","would","might"],"answer":0,"explanation":"Ought to is followed by the infinitive and means 'should'."},
{"id":"mv-021","topic":"Modal Verbs","level":"hard","q":"He ___ have left already; his coat is still here.","options":["mustn't","can't","needn't","won't"],"answer":1,"explanation":"Can't have + past participle expresses a negative deduction about the past.","accept":["can't","couldn't"]},
{"id":"mv-022","topic":"Modal Verbs","level":"hard","q":"The ground is wet. It ___ rained during the night.","options":["must have","must","may","can't have"],"answer":0,"explanation":"Must have + past participle expresses a logical deduction about the past.","accept":["must have","may have","might have","could have"]},
{"id":"mv-023","topic":"Modal Verbs","level":"hard","q":"I forgot to lock the door. I ___ locked it.","options":["must have","should have","can't have","needn't have"],"answer":1,"explanation":"Should have + past participle expresses regret or criticism about the past.","accept":["should have","ought to have"]},
{"id":"mv-024","topic":"Modal Verbs","level":"hard","q":"He ___ have been there, but I can't be sure.","options":["might","must","can't","needn't"],"answer":0,"explanation":"Might have + past participle expresses a past possibility.","accept":["might","may","could"]},
{"id":"mv-025","topic":"Modal Verbs","level":"hard","q":"You ___ have said that to her. It was very rude.","options":["mustn't","can't","shouldn't","won't"],"answer":2,"explanation":"Shouldn't have + past participle criticises a past action.","accept":["shouldn't","ought not to"]},
{"id":"mv-026","topic":"Modal Verbs","level":"hard","q":"She hasn't ___ able to solve the problem yet.","options":["could","can","being","been"],"answer":3,"explanation":"The present perfect of can is has/have been able to."},
{"id":"mv-027","topic":"Modal Verbs","level":"hard","q":"The train was ___ to arrive at nine, but it was late.","options":["suppose","supposing","supposed","supposes"],"answer":2,"explanation":"Be supposed to means something was expected or planned."},
{"id":"mv-028","topic":"Modal Verbs","level":"hard","q":"She ___ be home by now; her flight landed two hours ago.","options":["can't","needn't","shouldn't","should"],"answer":3,"explanation":"Should can express a reasonable expectation or probability.","accept":["should","must","will","ought to"]},
{"id":"mv-029","topic":"Modal Verbs","level":"hard","q":"I ___ have stayed longer, but I had to catch my train.","options":["must","can't","could","needn't"],"answer":2,"explanation":"Could have + past participle describes a past possibility that did not happen.","accept":["could","might"]},
{"id":"mv-030","topic":"Modal Verbs","level":"hard","q":"That ___ be the postman at the door. He always comes at this time.","options":["can't","mustn't","will","needn't"],"answer":2,"explanation":"Will can express a confident assumption about the present.","accept":["will","must","should"]},
{"id":"rs-001","topic":"Reported Speech","level":"easy","q":"Direct: 'I am tired.' Reported a week later: She said that she ___ tired.","options":["was","is","were","has been"],"answer":0,"explanation":"Reported speech usually moves one tense back: am/is becomes was."},
{"id":"rs-002","topic":"Reported Speech","level":"easy","q":"Direct: 'I live in Rio.' Reported later: He said that he ___ in Rio.","options":["live","living","lived","to live"],"answer":2,"explanation":"Present simple usually becomes past simple in reported speech."},
{"id":"rs-003","topic":"Reported Speech","level":"easy","q":"Direct: 'I will call you tomorrow.' Reported later: She said she ___ call me the next day.","options":["would","will","shall","can"],"answer":0,"explanation":"Will usually becomes would in reported speech."},
{"id":"rs-004","topic":"Reported Speech","level":"easy","q":"Direct: 'I have finished the report.' Reported later: He said he ___ finished the report.","options":["having","have","had","was"],"answer":2,"explanation":"Present perfect becomes past perfect: have finished becomes had finished."},
{"id":"rs-005","topic":"Reported Speech","level":"easy","q":"'Close the window,' she told me. She told me ___ the window.","options":["close","closing","to close","that close"],"answer":2,"explanation":"Reported commands use tell + object + to-infinitive."},
{"id":"rs-006","topic":"Reported Speech","level":"easy","q":"'Don't be late,' he said to us. He told us ___ late.","options":["don't be","not to be","not be","be not"],"answer":1,"explanation":"Negative commands use not + to-infinitive: told us not to be."},
{"id":"rs-007","topic":"Reported Speech","level":"easy","q":"'Where do you live?' she asked me. She asked me where I ___.","options":["do live","did live","lived","to live"],"answer":2,"explanation":"In reported questions, use statement word order without do/does/did.","accept":["lived","live"]},
{"id":"rs-008","topic":"Reported Speech","level":"easy","q":"Direct: 'I take the bus to work every day.' Reported later: He said he ___ the bus to work every day.","options":["taking","take","to take","took"],"answer":3,"explanation":"Present simple becomes past simple in reported speech.","accept":["took","used to take"]},
{"id":"rs-009","topic":"Reported Speech","level":"easy","q":"Direct: 'I can swim.' Reported later: She said she ___ swim.","options":["would","should","must","could"],"answer":3,"explanation":"Can usually becomes could in reported speech.","accept":["could","was able to"]},
{"id":"rs-010","topic":"Reported Speech","level":"easy","q":"He ___ me that he was busy.","options":["said","spoke","talked","told"],"answer":3,"explanation":"Tell needs a person after it (told me). Say does not (said that)."},
{"id":"rs-011","topic":"Reported Speech","level":"medium","q":"Direct: 'I am working on it now.' Reported later: He said he ___ working on it then.","options":["is","was","has been","had"],"answer":1,"explanation":"Present continuous becomes past continuous, and now becomes then."},
{"id":"rs-012","topic":"Reported Speech","level":"medium","q":"Direct: 'We went to Madrid last year.' Reported later: They said they ___ to Madrid the year before.","options":["had gone","have gone","were going","would go"],"answer":0,"explanation":"Past simple often becomes past perfect, and last year becomes the year before.","accept":["had gone","had been","went"]},
{"id":"rs-013","topic":"Reported Speech","level":"medium","q":"'I'll help you,' she promised. She promised ___ me.","options":["helping","help","to help","that help"],"answer":2,"explanation":"Promise is followed by a to-infinitive."},
{"id":"rs-014","topic":"Reported Speech","level":"medium","q":"'You should see a doctor,' he said to me. He advised me ___ a doctor.","options":["seeing","see","to see","that see"],"answer":2,"explanation":"Advise + object + to-infinitive."},
{"id":"rs-015","topic":"Reported Speech","level":"medium","q":"'Did you finish the report?' he asked. He asked me ___ I had finished the report.","options":["that","if","what","which"],"answer":1,"explanation":"Yes/no questions are reported with if or whether.","accept":["if","whether"]},
{"id":"rs-016","topic":"Reported Speech","level":"medium","q":"'I didn't take your pen,' she said. She denied ___ my pen.","options":["taking","to take","take","that take"],"answer":0,"explanation":"Deny is followed by the -ing form.","accept":["taking","having taken"]},
{"id":"rs-017","topic":"Reported Speech","level":"medium","q":"'Let's go to the cinema,' he said. He suggested ___ to the cinema.","options":["to go","going","go","that go"],"answer":1,"explanation":"Suggest is followed by the -ing form."},
{"id":"rs-018","topic":"Reported Speech","level":"medium","q":"'I'm sorry I'm late,' she said. She apologised ___ late.","options":["to be","being","for being","about be"],"answer":2,"explanation":"Apologise for + -ing.","accept":["for being","for arriving"]},
{"id":"rs-019","topic":"Reported Speech","level":"medium","q":"'Don't touch that!' she shouted. She warned us ___ that.","options":["to not touching","don't touch","not touching","not to touch"],"answer":3,"explanation":"Warn + object + (not) to-infinitive."},
{"id":"rs-020","topic":"Reported Speech","level":"medium","q":"'What time does the film start?' she asked me. She asked me what time the film ___.","options":["did start","start","started","to start"],"answer":2,"explanation":"In reported questions, use statement word order and move the tense back.","accept":["started","starts"]},
{"id":"rs-021","topic":"Reported Speech","level":"hard","q":"'If I were you, I would apply,' he said. He said that if he ___ in my position, he would apply.","options":["is","will be","has been","were"],"answer":3,"explanation":"Unreal conditionals keep were in reported speech.","accept":["were","was"]},
{"id":"rs-022","topic":"Reported Speech","level":"hard","q":"Direct: 'I have been waiting for an hour.' She complained that she ___ for an hour.","options":["had been waiting","has been waiting","have been waiting","is waiting"],"answer":0,"explanation":"Present perfect continuous becomes past perfect continuous.","accept":["had been waiting","had waited"]},
{"id":"rs-023","topic":"Reported Speech","level":"hard","q":"'If I had known, I would have helped,' she said. She said that if she ___ known, she would have helped.","options":["has","have","would have","had"],"answer":3,"explanation":"Third conditional sentences do not change in reported speech."},
{"id":"rs-024","topic":"Reported Speech","level":"hard","q":"He ___ that he had never met her before.","options":["persuaded","advised","reminded","claimed"],"answer":3,"explanation":"Claim can be followed by a that-clause. Persuade, advise and remind need an object first.","accept":["claimed","said","stated","insisted","maintained","explained","declared"]},
{"id":"rs-025","topic":"Reported Speech","level":"hard","q":"He ___ me to reconsider my decision.","options":["suggested","admitted","denied","urged"],"answer":3,"explanation":"Urge + object + to-infinitive.","accept":["urged","encouraged","advised","asked","told","persuaded","begged"]},
{"id":"rs-026","topic":"Reported Speech","level":"hard","q":"She ___ having made a mistake.","options":["admitted","suggested","persuaded","reminded"],"answer":0,"explanation":"Admit (and deny) can be followed by the -ing form.","accept":["admitted","denied"]},
{"id":"rs-027","topic":"Reported Speech","level":"hard","q":"'Why didn't you call me?' she asked him. Choose the correct report.","options":["She asked him why he hadn't called her.","She asked him why didn't he call her.","She asked him why he didn't called her.","She asked him why he doesn't call her."],"answer":0,"explanation":"In reported questions, use statement word order and move the tense back (didn't call becomes hadn't called).","w":{"q":"Report this question: 'Why didn't you call me?' she asked him.","accept":["She asked him why he hadn't called her.","She asked him why he didn't call her."]}},
{"id":"rs-028","topic":"Reported Speech","level":"hard","q":"'Could you open the window, please?' he asked me. Choose the correct report.","options":["He asked me could I open the window.","He asked me to open the window.","He asked me opening the window.","He asked me that I open the window."],"answer":1,"explanation":"Polite requests are usually reported with ask + object + to-infinitive.","w":{"q":"Report this request: 'Could you open the window, please?' he asked me.","accept":["He asked me to open the window.","He asked me if I could open the window.","He asked me whether I could open the window."]}},
{"id":"rs-029","topic":"Reported Speech","level":"hard","q":"Reported a week later, in a different place: 'I'll meet you here tomorrow,' she said.","options":["She said she will meet me here tomorrow.","She said she would meet me there the following day.","She said she met me there the following day.","She said she meets me there the following day."],"answer":1,"explanation":"Will becomes would, here becomes there, and tomorrow becomes the following day.","w":{"q":"Report this a week later, in a different place: 'I'll meet you here tomorrow,' she said.","accept":["She said she would meet me there the following day.","She said she would meet me there the next day."]}},
{"id":"rs-030","topic":"Reported Speech","level":"hard","q":"'How long have you worked here?' he asked me. He wanted to know how long I ___ there.","options":["had worked","did work","working","to work"],"answer":0,"explanation":"Present perfect becomes past perfect, and the question uses statement word order.","accept":["had worked","had been working","worked"]},
{"id":"pv-001","topic":"Phrasal Verbs","level":"easy","q":"I don't know this word. I'll look it ___ in the dictionary.","options":["on","up","at","for"],"answer":1,"explanation":"Look up means to search for information."},
{"id":"pv-002","topic":"Phrasal Verbs","level":"easy","q":"Please fill ___ this form and hand it in.","options":["in","on","by","at"],"answer":0,"explanation":"Fill in (or fill out) means to complete a form.","accept":["in","out"]},
{"id":"pv-003","topic":"Phrasal Verbs","level":"easy","q":"Don't give ___! You're almost there.","options":["on","at","by","up"],"answer":3,"explanation":"Give up means to stop trying.","accept":["up","in"]},
{"id":"pv-004","topic":"Phrasal Verbs","level":"easy","q":"The meeting was called ___ because of the storm.","options":["off","out","up","on"],"answer":0,"explanation":"Call off means to cancel."},
{"id":"pv-005","topic":"Phrasal Verbs","level":"easy","q":"We ran ___ of milk, so I went to the shop.","options":["off","out","up","down"],"answer":1,"explanation":"Run out of means to have none left."},
{"id":"pv-006","topic":"Phrasal Verbs","level":"easy","q":"Turn ___ the TV. It's too loud.","options":["down","up","on","in"],"answer":0,"explanation":"Turn down means to reduce the volume.","accept":["down","off"]},
{"id":"pv-007","topic":"Phrasal Verbs","level":"easy","q":"The car broke ___ on the highway, so we called a mechanic.","options":["off","down","up","out"],"answer":1,"explanation":"Break down means to stop working."},
{"id":"pv-008","topic":"Phrasal Verbs","level":"easy","q":"She grew ___ in a small town.","options":["out","off","on","up"],"answer":3,"explanation":"Grow up means to become an adult."},
{"id":"pv-009","topic":"Phrasal Verbs","level":"easy","q":"Can you pick me ___ at the airport at six?","options":["on","up","off","out"],"answer":1,"explanation":"Pick up means to collect someone by car."},
{"id":"pv-010","topic":"Phrasal Verbs","level":"easy","q":"He took ___ his jacket because it was warm inside.","options":["up","in","off","over"],"answer":2,"explanation":"Take off means to remove clothing."},
{"id":"pv-011","topic":"Phrasal Verbs","level":"medium","q":"We need to come ___ with a better solution.","options":["up","on","off","over"],"answer":0,"explanation":"Come up with means to think of an idea."},
{"id":"pv-012","topic":"Phrasal Verbs","level":"medium","q":"He was offered the job, but he turned it ___.","options":["up","on","down","off"],"answer":2,"explanation":"Turn down means to refuse."},
{"id":"pv-013","topic":"Phrasal Verbs","level":"medium","q":"I'll look ___ the children while you're away.","options":["after","for","into","at"],"answer":0,"explanation":"Look after means to take care of."},
{"id":"pv-014","topic":"Phrasal Verbs","level":"medium","q":"Let's put ___ the meeting until next week.","options":["off","up","on","out"],"answer":0,"explanation":"Put off means to postpone."},
{"id":"pv-015","topic":"Phrasal Verbs","level":"medium","q":"She gets ___ well with her colleagues.","options":["on","in","at","by"],"answer":0,"explanation":"Get on (or get along) with means to have a good relationship.","accept":["on","along"]},
{"id":"pv-016","topic":"Phrasal Verbs","level":"medium","q":"The company plans to take ___ its main competitor.","options":["up","off","in","over"],"answer":3,"explanation":"Take over means to gain control of a company."},
{"id":"pv-017","topic":"Phrasal Verbs","level":"medium","q":"We can't put ___ with this noise any longer.","options":["on","in","up","off"],"answer":2,"explanation":"Put up with means to tolerate."},
{"id":"pv-018","topic":"Phrasal Verbs","level":"medium","q":"I'll find ___ what time the train leaves.","options":["up","out","off","over"],"answer":1,"explanation":"Find out means to discover information."},
{"id":"pv-019","topic":"Phrasal Verbs","level":"medium","q":"She ran ___ an old friend at the supermarket.","options":["out","up","into","off"],"answer":2,"explanation":"Run into means to meet by chance.","accept":["into","across"]},
{"id":"pv-020","topic":"Phrasal Verbs","level":"medium","q":"Could you point ___ the main problem in this report?","options":["up","out","off","in"],"answer":1,"explanation":"Point out means to draw attention to something."},
{"id":"pv-021","topic":"Phrasal Verbs","level":"hard","q":"The company is phasing ___ the old software and replacing it.","options":["off","out","down","away"],"answer":1,"explanation":"Phase out means to stop using something gradually."},
{"id":"pv-022","topic":"Phrasal Verbs","level":"hard","q":"He decided to step ___ as CEO after twenty years.","options":["off","out","away","down"],"answer":3,"explanation":"Step down means to resign from a position."},
{"id":"pv-023","topic":"Phrasal Verbs","level":"hard","q":"We need to cut ___ on expenses this quarter.","options":["off","up","in","down"],"answer":3,"explanation":"Cut down on (or cut back on) means to reduce.","accept":["down","back"]},
{"id":"pv-024","topic":"Phrasal Verbs","level":"hard","q":"The new policy will be rolled ___ across all branches next month.","options":["off","up","down","out"],"answer":3,"explanation":"Roll out means to introduce something gradually."},
{"id":"pv-025","topic":"Phrasal Verbs","level":"hard","q":"I can't figure ___ why the system keeps crashing.","options":["up","off","in","out"],"answer":3,"explanation":"Figure out means to understand or solve."},
{"id":"pv-026","topic":"Phrasal Verbs","level":"hard","q":"The deal fell ___ at the last minute.","options":["off","out","through","away"],"answer":2,"explanation":"Fall through means to fail to happen.","accept":["through","apart"]},
{"id":"pv-027","topic":"Phrasal Verbs","level":"hard","q":"It took her a while to get ___ the shock of losing her job.","options":["off","out","over","up"],"answer":2,"explanation":"Get over means to recover from something."},
{"id":"pv-028","topic":"Phrasal Verbs","level":"hard","q":"Don't bring ___ the budget during the meeting; it will cause arguments.","options":["on","off","out","up"],"answer":3,"explanation":"Bring up means to mention a topic."},
{"id":"pv-029","topic":"Phrasal Verbs","level":"hard","q":"We're trying to wrap ___ the project before the deadline.","options":["out","up","off","in"],"answer":1,"explanation":"Wrap up means to finish."},
{"id":"pv-030","topic":"Phrasal Verbs","level":"hard","q":"She takes ___ her mother; they have the same smile.","options":["over","up","after","on"],"answer":2,"explanation":"Take after means to resemble a family member."},
{"id":"lw-001","topic":"Linking Words","level":"easy","q":"I was tired, ___ I went to bed early.","options":["but","because","so","although"],"answer":2,"explanation":"So introduces a result."},
{"id":"lw-002","topic":"Linking Words","level":"easy","q":"He didn't come ___ he was ill.","options":["so","because","but","although"],"answer":1,"explanation":"Because introduces a reason.","accept":["because","as","since"]},
{"id":"lw-003","topic":"Linking Words","level":"easy","q":"She is rich, ___ she is not happy.","options":["so","because","if","but"],"answer":3,"explanation":"But introduces a contrast.","accept":["but","yet"]},
{"id":"lw-004","topic":"Linking Words","level":"easy","q":"___ it was raining, we went for a walk.","options":["Although","Because","So","But"],"answer":0,"explanation":"Although introduces a contrast within one sentence.","accept":["Although","Though","Even though"]},
{"id":"lw-005","topic":"Linking Words","level":"easy","q":"You can borrow my car ___ you drive carefully.","options":["although","because","if","but"],"answer":2,"explanation":"If introduces a condition.","accept":["if","as long as","provided","providing"]},
{"id":"lw-006","topic":"Linking Words","level":"easy","q":"I'll call you ___ I arrive.","options":["although","when","but","unless"],"answer":1,"explanation":"When introduces a time.","accept":["when","as soon as","once","after"]},
{"id":"lw-007","topic":"Linking Words","level":"easy","q":"She studied hard ___ pass the exam.","options":["for","so","because","to"],"answer":3,"explanation":"To + verb expresses purpose.","accept":["to","in order to","so as to"]},
{"id":"lw-008","topic":"Linking Words","level":"easy","q":"We were late ___ the traffic.","options":["because","although","because of","so"],"answer":2,"explanation":"Because of is followed by a noun.","accept":["because of","due to","owing to"]},
{"id":"lw-009","topic":"Linking Words","level":"easy","q":"___ the rain, we enjoyed the trip.","options":["Although","Because","Despite","However"],"answer":2,"explanation":"Despite is followed by a noun or an -ing form.","accept":["Despite","In spite of"]},
{"id":"lw-010","topic":"Linking Words","level":"easy","q":"First, mix the flour and eggs. ___, add the milk.","options":["Then","Although","Because","Unless"],"answer":0,"explanation":"Then (or next) shows the sequence of steps.","accept":["Then","Next","After that","Afterwards"]},
{"id":"lw-011","topic":"Linking Words","level":"medium","q":"The hotel was cheap. ___, it was very clean.","options":["However","Therefore","Otherwise","Moreover"],"answer":3,"explanation":"Moreover adds a further point.","accept":["Moreover","Furthermore","Also","In addition","Besides"]},
{"id":"lw-012","topic":"Linking Words","level":"medium","q":"The product is expensive. ___, it is worth the price.","options":["Moreover","However","Therefore","Besides"],"answer":1,"explanation":"However introduces a contrast.","accept":["However","Nevertheless","Even so","Still"]},
{"id":"lw-013","topic":"Linking Words","level":"medium","q":"He didn't study. ___, he failed the exam.","options":["However","Although","Despite","Therefore"],"answer":3,"explanation":"Therefore introduces a result.","accept":["Therefore","Consequently","As a result","Thus","Hence"]},
{"id":"lw-014","topic":"Linking Words","level":"medium","q":"___ her age, she runs marathons.","options":["Although","Because of","Unless","Despite"],"answer":3,"explanation":"Despite is followed by a noun phrase.","accept":["Despite","In spite of","Regardless of"]},
{"id":"lw-015","topic":"Linking Words","level":"medium","q":"She saved money ___ she could buy a car.","options":["in order","because","so that","although"],"answer":2,"explanation":"So that introduces a purpose with a full clause.","accept":["so that","so"]},
{"id":"lw-016","topic":"Linking Words","level":"medium","q":"I'll go to the party ___ I have too much work.","options":["if","unless","because","although"],"answer":1,"explanation":"Unless means 'if not'."},
{"id":"lw-017","topic":"Linking Words","level":"medium","q":"She speaks Spanish, ___ her sister speaks French.","options":["because","unless","so","whereas"],"answer":3,"explanation":"Whereas (or while) compares two different things.","accept":["whereas","while","but"]},
{"id":"lw-018","topic":"Linking Words","level":"medium","q":"The flight was delayed ___ bad weather.","options":["because","although","due to","so that"],"answer":2,"explanation":"Due to is followed by a noun.","accept":["due to","because of","owing to"]},
{"id":"lw-019","topic":"Linking Words","level":"medium","q":"___ I was walking home, I saw an accident.","options":["Despite","While","Therefore","Unless"],"answer":1,"explanation":"While introduces two things happening at the same time.","accept":["While","As","When"]},
{"id":"lw-020","topic":"Linking Words","level":"medium","q":"We stayed inside ___ the weather was terrible.","options":["since","unless","although","whereas"],"answer":0,"explanation":"Since (or because/as) gives a reason.","accept":["since","because","as"]},
{"id":"lw-021","topic":"Linking Words","level":"hard","q":"___ having little experience, she got the job.","options":["Despite","Whereas","Unless","Owing to"],"answer":0,"explanation":"Despite + -ing expresses contrast.","accept":["Despite","In spite of"]},
{"id":"lw-022","topic":"Linking Words","level":"hard","q":"The results were poor; ___, the team remained optimistic.","options":["consequently","moreover","nevertheless","otherwise"],"answer":2,"explanation":"Nevertheless introduces a contrast with what was just said.","accept":["nevertheless","nonetheless","however","even so","still"]},
{"id":"lw-023","topic":"Linking Words","level":"hard","q":"You must wear a seatbelt; ___, you could be fined.","options":["otherwise","moreover","whereas","nevertheless"],"answer":0,"explanation":"Otherwise means 'if you do not'.","accept":["otherwise","or else"]},
{"id":"lw-024","topic":"Linking Words","level":"hard","q":"Hard ___ he tried, he couldn't lift the box.","options":["as","since","unless","whereas"],"answer":0,"explanation":"Adjective + as/though + subject + verb expresses concession: however hard he tried.","accept":["as","though"]},
{"id":"lw-025","topic":"Linking Words","level":"hard","q":"In the north the climate is cold; ___, in the south it is warm.","options":["by contrast","as a result","for instance","in addition"],"answer":0,"explanation":"By contrast (or in contrast) compares two opposite things.","accept":["by contrast","in contrast","on the other hand"]},
{"id":"lw-026","topic":"Linking Words","level":"hard","q":"Many countries are investing in green energy; ___, Norway and Denmark.","options":["however","therefore","for instance","otherwise"],"answer":2,"explanation":"For instance (or for example) introduces an example.","accept":["for instance","for example"]},
{"id":"lw-027","topic":"Linking Words","level":"hard","q":"We will approve the budget ___ the costs are reduced.","options":["even though","provided that","in case","whereas"],"answer":1,"explanation":"Provided that means 'only if'.","accept":["provided that","provided","providing","as long as","on condition that","if"]},
{"id":"lw-028","topic":"Linking Words","level":"hard","q":"Take an umbrella ___ it rains.","options":["in case","unless","although","so that"],"answer":0,"explanation":"In case means 'because it might happen'."},
{"id":"lw-029","topic":"Linking Words","level":"hard","q":"She worked abroad for ten years; ___, she speaks three languages fluently.","options":["in contrast","as a result","nevertheless","for instance"],"answer":1,"explanation":"As a result introduces a consequence.","accept":["as a result","consequently","therefore","hence","thus"]},
{"id":"lw-030","topic":"Linking Words","level":"hard","q":"The measure was introduced ___ reduce pollution.","options":["so that","in order","as to","in order to"],"answer":3,"explanation":"In order to + verb expresses purpose.","accept":["in order to","so as to","to"]}
];
